Open `src/plugin.ts` and replace its content with the following code. This implementation assumes that you have already set up the oneWelcome iOS SDK in your Xcode project and have the `SharedUserClient` instance available.

```typescript
import { PluginListenerHandle } from '@capacitor/core';

interface OneWelcomePlugin {
  authenticateUser(options: { userProfile: string; authenticator?: string }): Promise<void>;
  addListener(eventName: 'onAuthStart' | 'onPinChallenge' | 'onBiometricChallenge' | 'onCustomAuthChallenge' | 'onAuthSuccess' | 'onAuthFailure', listenerFunc: (data: any) => void): Promise<PluginListenerHandle> & PluginListenerHandle;
  removeAllListeners(): Promise<void>;
}

export const OneWelcome = (() => {
  const plugin: OneWelcomePlugin = {
    authenticateUser: async (options) => {
      // Import the oneWelcome SDK here if not already imported in your main app
      // import { SharedUserClient } from 'one-welcome-sdk';

      // Assuming SharedUserClient is already imported and initialized in your main app
      const userProfile = options.userProfile;
      const authenticator = options.authenticator || null;

      SharedUserClient.instance.authenticateUserWith(
        profile: userProfile,
        authenticator: authenticator,
        delegate: new OneWelcomeDelegate()
      );
    },

    addListener: (eventName, listenerFunc) => {
      const listener = new OneWelcomeDelegate();
      listener[eventName] = listenerFunc;
      return listener;
    },

    removeAllListeners: async () => {
      // No-op for now, as we're not storing any listeners
    },
  };

  class OneWelcomeDelegate {
    onAuthStart(userProfile: string, authenticator: string) {
      console.log(`Authentication started for user ${userProfile} with authenticator ${authenticator}`);
      // Emit 'onAuthStart' event
      plugin.emit('onAuthStart', { userProfile, authenticator });
    }

    onPinChallenge(pinChallenge: string) {
      console.log(`PIN challenge received: ${pinChallenge}`);
      // Emit 'onPinChallenge' event
      plugin.emit('onPinChallenge', { pinChallenge });
    }

    onBiometricChallenge(biometricChallenge: string) {
      console.log(`Biometric challenge received: ${biometricChallenge}`);
      // Emit 'onBiometricChallenge' event
      plugin.emit('onBiometricChallenge', { biometricChallenge });
    }

