To create a Capacitor plugin for integrating the oneWelcome iOS SDK into your React microfrontends, follow these detailed steps. We'll create a separate repository for the plugin and ensure it works with your existing single-spa root and React microfrontends.

1. **Initialize the plugin repository**

First, create a new directory for your plugin and navigate into it:

```bash
mkdir one-welcome-plugin
cd one-welcome-plugin
```

Initialize a new npm package and Capacitor plugin:

```bash
npm init -y
npm init @capacitor/plugin
```

Follow the prompts, and when asked for the plugin ID, use `com.yourcompany.onewelcome`. Replace `yourcompany` with your actual company name.

2. **Set up the plugin structure**

After running `npm init @capacitor/plugin`, you'll have the following structure:

```
one-welcome-plugin/
|-- src/
|   |-- __tests__/
|   |-- index.ts
|   |-- plugin.ts
|-- tsconfig.json
|-- package.json
|-- capacitor.config.ts
```

3. **Implement the plugin**

Open `src/plugin.ts` and replace its content with the following code. This implementation assumes that you have already set up the oneWelcome iOS SDK in your Xcode project and have the necessary certificates and configurations in place.

```typescript
import { PluginListenerHandle } from '@capacitor/core';
import { PluginListenerHandle, CapacitorPlugin } from '@capacitor/core';
import { AuthenticationDelegate, SharedUserClient, UserProfile, Authenticator } from 'one-welcome-sdk'; // Import the oneWelcome SDK

interface OneWelcomePlugin {
  authenticateUser(options: { userProfile: string; authenticator?: string }): Promise<void>;
  addListener(eventName: 'onAuthStart' | 'onPinChallenge' | 'onBiometricChallenge' | 'onCustomAuthChallenge' | 'onAuthSuccess' | 'onAuthFailure', listenerFunc: (data: any) => void): Promise<PluginListenerHandle> & PluginListenerHandle;
  removeAllListeners(): Promise<void>;
}

export class OneWelcomePlugin extends CapacitorPlugin<OneWelcomePlugin> implements AuthenticationDelegate {
  static getPlugin(id: string): OneWelcomePlugin {
    return new OneWelcomePlugin();
  }

  private userClient: SharedUserClient;
  private listenerHandles: Map<string, PluginListenerHandle> = new Map();

  constructor() {
    super();
    this.userClient = SharedUserClient.instance;
    this.userClient.delegate = this;
  }

  async authenticateUser(options: { userProfile: string; authenticator?: string }): Promise<void> {
    const userProfile = UserProfile(userProfile: options.userProfile);
    let authenticator: Authenticator | undefined;

    if (options.authenticator) {
      authenticator = Authenticator(options.authenticator);
    }

    await this.userClient.authenticateUserWith(profile: userProfile, authenticator: authenticator, delegate: this);
  }

  // AuthenticationDelegate methods
  userClient(_: SharedUserClient, didStartAuthenticationForUser userProfile: UserProfile, authenticator: Authenticator) {
    this.notifyListeners('onAuthStart', { userProfile, authenticator });
  }

  userClient(_: SharedUserClient, didReceivePinChallenge challenge: String) {
    this.notifyListeners('onPinChallenge', { challenge });
  }

